import { create_expense_category } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    addConfiguration: Boolean
  },
  data() {
    return {
      expenseName: "",
      // expensecategory: "",
      // expensecategoryitems: [],
      loading: false
    };
  },
  watch: {
    addConfiguration: {
      async handler() {
        if (this.addConfiguration == true) {}
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
      this.$emit("clicked", 0);
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form?.validate?.();
      if (valid) {
        this.create_master_designations();
      }
    },
    async create_master_designations() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_expense_category, {
          input: {
            // team_name: this.broadcastName,

            organization_id: data.organization.organization_id,
            expense_name: this.expenseName,
            user_email_id: data.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.create_expense_category);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("categoeryRefresh", "refresh");
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
